{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the objective to maximize total profit (revenue from selling all produced units minus raw material cost and processing cost), or is it to minimize total cost, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

